head.script:
scwin.makeDataList = function(id, obj) {
    if (WebSquare.wUnit.getObjById(id) != undefined) {
        $w.data.remove(id);
    }
    $w.data.create({
        "id": id,
        "type": "dataList",
        "option": {
            "useData": false
        },
        "columnInfo": obj
    });
}
scwin.setColumnID = function(obj) {
    //debugger;
    var column = {};
    var columnArr = [];
    var gridHeader = "",
        gridBody = "";
    //json의 첫번째 데이터에서 컬럼의 id와 개수 정보 확
    for (var k in obj[0]) {
        //dataList를 동적으로 만들기 위한 컬럼 정
        column = {};
        column["id"] = k;
        column["dataType"] = "text";
        columnArr.push(column);
        //gridView의 컬럼 정보 정의
        gridHeader += '<w2:column blockSelect="false" id="' + 'h' + k + '" style="height:20px" inputType="text" width="70" value="' + k + '" useFilter="true"></w2:column>';
        if (k == 'col1') {
            gridBody += '<w2:column blockSelect="false" id="' + k + '" style="height:20px" inputType="text" width="70" colMerge="true"></w2:column>'
        } else {
            gridBody += '<w2:column blockSelect="false" id="' + k + '" style="height:20px" inputType="text" width="70" ></w2:column>'
        }
    }
    scwin.makeDataList("dataList1", columnArr);
    //gridView 정보 정의
    //xml 형식을 정의 하면 <w2:gridView 에 xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" 포함 합니다.
    var gridStr = '<w2:gridView xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" dataList="dataList1" scrollByColumn="false" id="gridView1" style="width: 500px;height: 350px;" fixedColumnWithHidden="true" useShiftKey="false" ev:ongroupby="scwin.ongrp" autoFit="allColumn" groupbyZone="true" groupbyFilterBox="true" customFilterBox="true" useFilterList="true" rowNumWidth="" >' +
        '<w2:header id="header1" style="">' +
        '<w2:row id="row1" style="">' +
        gridHeader +
        '</w2:row>' +
        '</w2:header>' +
        '<w2:gBody id="gBody1" style="">' +
        '<w2:row id="row2" style="">' +
        gridBody +
        '</w2:row>' +
        '</w2:gBody>' +
        '</w2:gridView>';
    gridView1.setGridStyle(WebSquare.xml.parse(gridStr, true));
    dataList1.setJSON(obj);
}
scwin.ongrp = function(options) {
    options.groupbyHeader = [];
    options.groupbyFooter = [];
    gridView1.groupby(options);
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#gridView1_hcol1', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 '동적그리드'버튼을 클릭한다.
    //1. After running the sample, click the 'Dynamic Grid' button.
    //Verify step 1. The gridView is displayed and displayed.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_body_tbody').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. colMerge되어진 'col1'항목을 필터링한다.(예:test1, test2)
    //2. Filter colMerge 'col1' items (eg test1, test2)
    //Verify step 2. Filtered by test1 and test2.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_hcol1_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[3].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[4].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_1').text() == 'test1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_2_1').text() == 'test2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 'col1'항목을 groupby 시킨다.
    //3. Group the 'col1' item.
    //Verify step 3. The 'col1' item is groupby.
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text() == 'col1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_1_1').text() == 'test1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_2_1').text() == 'test1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_5_1').text() == 'test2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_6_1').text() == 'test2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
